local a={}a.id="fcssync"a.title="FCS SYNC"a.FRESH_MS=3000;function a.linkStatus(b,c)if not b.running then return"STOPPED"end;if b.lastSeen and c-b.lastSeen<=a.FRESH_MS then return"FCS ACTIVE"end;return"WAITING FOR FCS"end;function a._onButton(d,e,c)if e=="start"then d.cfgserver:start()d.uiRev=(d.uiRev or 0)+1;return e elseif e=="stop"then d.cfgserver:stop()d.uiRev=(d.uiRev or 0)+1;return e end;return nil end;function a.build(f,g,d,h)local i,j=g:getSize()local k=2;local l=math.max(1,i-2)local m=g:addLabel({x=k,y=2,width=l,height=1,autoSize=false,text=a.title})local n=3;local o=g:addLabel({x=k,y=n,width=l,height=1,autoSize=false,text="SERVER: --"})local p=g:addLabel({x=k,y=n+1,width=l,height=1,autoSize=false,text="LINK: --"})local q=n+3;local r=math.max(1,math.floor(l/2))local s=g:addButton({x=k,y=q,width=r,height=1,text="START"})local t=g:addButton({x=k+r,y=q,width=math.max(1,l-r),height=1,text="STOP"})local u=g:addButton({x=k,y=q+1,width=l,height=1,text="< BACK"})s:onClick(function()a._onButton(d,"start",os.epoch("utc"))end)t:onClick(function()a._onButton(d,"stop",os.epoch("utc"))end)u:onClick(function()if h then h:pop()end end)local function v(w)local b=d.cfgserver:status()local c=os.epoch("utc")local x=b.running and"RUNNING"or"STOPPED"o:setText("SERVER: "..x)local y=a.linkStatus(b,c)p:setText("LINK: "..y)s:setEnabled(not b.running)t:setEnabled(b.running)end;return{id=a.id,apply=v,elements={headerLabel=m,serverLbl=o,linkLbl=p,startBtn=s,stopBtn=t,backBtn=u}}end;return a